def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\d+|[A-Z][1-9]\d?|SUM|MIN|MAX|IF|<>|<=|>=|[+\-*/(),:<>==]"
    )
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "~": 4,
    }

    def parse(content):
        if not content.startswith("="):
            return ("num", int(content))

        tokens = token_pattern.findall(content[1:])
        output = []
        operators = []
        expecting_operand = True
        i = 0

        def reduce_operator():
            op = operators.pop()
            if op == "~":
                output.append(("neg", output.pop()))
            else:
                right = output.pop()
                left = output.pop()
                output.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                output.append(("num", int(token)))
                expecting_operand = False
            elif token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(["(", token, 0])
                i += 1  # Skip the function's opening parenthesis.
                expecting_operand = True
            elif token == "(":
                operators.append(["(", None, 0])
                expecting_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                operators[-1][2] += 1
                expecting_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                _, function, commas = operators.pop()
                if function is not None:
                    count = commas + 1
                    args = output[-count:]
                    del output[-count:]
                    output.append(("call", function, args))
                expecting_operand = False
            elif token in precedence:
                op = "~" if token == "-" and expecting_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "~"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(op)
                expecting_operand = True
            else:
                if i + 1 < len(tokens) and tokens[i + 1] == ":":
                    output.append(("range", token, tokens[i + 2]))
                    i += 2
                else:
                    output.append(("ref", token))
                expecting_operand = False
            i += 1

        while operators:
            reduce_operator()
        return output[0]

    def function_items(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue

            first, second = arg[1], arg[2]
            col1, col2 = sorted((ord(first[0]), ord(second[0])))
            row1, row2 = sorted((int(first[1:]), int(second[1:])))
            for row in range(row1, row2 + 1):
                for col in range(col1, col2 + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("ref", name)

    values = {}
    active = set()

    def evaluate(name):
        stack = [("ref", name)]
        results = []

        while stack:
            task = stack.pop()
            kind = task[0]

            if kind == "ref":
                cell = task[1]
                if cell in values:
                    results.append(values[cell])
                elif cell not in cells:
                    results.append(0)
                elif cell in active:
                    results.append("#CYCLE!")
                else:
                    active.add(cell)
                    stack.append(("finish_cell", cell))
                    stack.append(("eval", parse(cells[cell])))

            elif kind == "finish_cell":
                cell = task[1]
                active.remove(cell)
                values[cell] = results[-1]

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "num":
                    results.append(node[1])
                elif node_kind == "ref":
                    stack.append(("ref", node[1]))
                elif node_kind == "neg":
                    stack.append(("neg",))
                    stack.append(("eval", node[1]))
                elif node_kind == "binary":
                    stack.append(("binary_left", node[1], node[3]))
                    stack.append(("eval", node[2]))
                else:
                    function, args = node[1], node[2]
                    if function == "IF":
                        stack.append(("if", args[1], args[2]))
                        stack.append(("eval", args[0]))
                    else:
                        stack.append(
                            ("function_next", function, iter(function_items(args)), None)
                        )

            elif kind == "neg":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    stack.append(("binary_right", task[1], left))
                    stack.append(("eval", task[2]))

            elif kind == "binary_right":
                right = results.pop()
                op, left = task[1], task[2]
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                else:
                    results.append(left >= right)

            elif kind == "if":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    stack.append(("eval", task[1] if condition else task[2]))

            elif kind == "function_next":
                function, items, aggregate = task[1:]
                item = next(items, None)
                if item is None:
                    results.append(0 if aggregate is None else aggregate)
                else:
                    stack.append(("function_value", function, items, aggregate))
                    stack.append(("eval", item))

            else:  # function_value
                function, items, aggregate = task[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if aggregate is None:
                        aggregate = value
                    elif function == "SUM":
                        aggregate += value
                    elif function == "MIN":
                        aggregate = min(aggregate, value)
                    else:
                        aggregate = max(aggregate, value)
                    stack.append(("function_next", function, items, aggregate))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
